import React from 'react';
import { Navigate } from 'react-router-dom';

const ProtectedRoute = ({ children, allowedRole }) => {
  // Retrieve token and user role stored during login
  const token = localStorage.getItem('auth-token');
  const userRole = localStorage.getItem('user-role'); // e.g., 'Admin', 'User', 'Seller'

  // If no auth token exists, redirect to login
  if (!token) {
    return <Navigate to="/login" replace />;
  }

  // If role doesn't match allowedRole, redirect to home page
  if (userRole !== allowedRole) {
    alert("Access Denied: You do not have permission to access the Admin Panel.");
    return <Navigate to="/" replace />;
  }

  return children;
};

export default ProtectedRoute;
